// и таблицы вместе с журналом миграций остаются — повторная установка доводит закладку заново.
// id обязан совпадать с именем каталога — расхождение ловит реестр (core/apps.php).
return [
    'id' => 'brokenseed',
    'title' => 'Раздел со сбойной закладкой',
    'version' => '1.0.0',
    'requiresCore' => '1.1.0',
    'privatePaths' => [],
    'sql' => __DIR__ . '/sql',
    'seed' => __DIR__ . '/seed.php',
];
